firestoreRules:
rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    function isAdmin() {
      return request.auth != null && (
        request.auth.token.email == 'lixpang0427@gmail.com' ||
        (exists(/databases/$(database)/documents/users/$(request.auth.uid)) && 
         get(/databases/$(database)/documents/users/$(request.auth.uid)).data.role == 'admin')
      );
    }
    match /users/{userId} {
      allow read: if request.auth != null && (request.auth.uid == userId || isAdmin());
      allow write: if request.auth != null && (request.auth.uid == userId || isAdmin());
    }
    match /records/{recordId} {
      allow read, update, delete: if request.auth != null && ((resource == null || resource.data.userId == request.auth.uid) || isAdmin());
      allow create: if request.auth != null && request.resource.data.userId == request.auth.uid;
    }
    match /custom_templates/{templateId} {
      allow read, update, delete: if request.auth != null && ((resource == null || resource.data.userId == request.auth.uid) || isAdmin());
      allow create: if request.auth != null && request.resource.data.userId == request.auth.uid;
    }
    match /system_templates/{templateId} {
      allow read: if true;
      allow write: if request.auth != null && isAdmin();
    }
    match /system_metrics/{metricId} {
      allow read, write: if request.auth != null;
    }
  }
}
